class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}  # name -> (weight, kind)
        self.grades = {}  # student -> {assignment -> grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")

        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if student not in self.grades:
            # If student has no grades recorded, use default of 2.0 for all assignments
            if not self.assignments:
                return 2.0
            total_weight = 0.0
            weighted_sum = 0.0
            for assignment_name, (weight, _) in self.assignments.items():
                total_weight += weight
                weighted_sum += 2.0 * weight
            if total_weight == 0.0:
                return 2.0
            return round(weighted_sum / total_weight, 2)

        # Calculate weighted average
        total_weight = 0.0
        weighted_sum = 0.0

        for assignment_name, (weight, _) in self.assignments.items():
            total_weight += weight
            # Use recorded grade if available, otherwise default to 2.0
            grade = self.grades[student].get(assignment_name, 2.0)
            weighted_sum += grade * weight

        if total_weight == 0.0:
            return 2.0

        result = weighted_sum / total_weight
        return round(result, 2)
